# Generated by Descant: acceptance tests.

require "rails_helper"
require "socket"
require "tempfile"
require_relative "../../../spec/support/timekeeping/fake_relay"

RSpec.describe RelayJob, "run by the configured Solid Queue processes", type: :request do
  self.use_transactional_tests = false

  it "delivers a committed outbox row through the configured worker only after a request-side pause is resumed" do
    app_root = File.expand_path("../..", __dir__)
    fake_timekeeping = TimekeepingContract::FakeTimekeeping.new
    token = fake_timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    projection = TimekeepingContract::FakeRelay.new(source: fake_timekeeping)
    posted_entry_ids = []
    posted_lock = Mutex.new

    # A real listener: the worker posts from another process, which no stub here can see.
    listener = TCPServer.new("127.0.0.1", 0)
    snapshot_url = "http://127.0.0.1:#{listener.addr[1]}"
    listener_thread = Thread.new do
      loop do
        client = listener.accept
        request_line = client.gets.to_s
        headers = {}
        while (line = client.gets) && line != "\r\n"
          name, value = line.split(":", 2)
          headers[name.strip.downcase] = value.to_s.strip
        end
        body = JSON.parse(client.read(headers.fetch("content-length", "0").to_i))
        path = request_line.split[1]
        posted_lock.synchronize do
          posted_entry_ids.concat(body.fetch("snapshots").map { |item| item.dig("entry", "id") })
        end
        answer = projection.call("POST", path,
                                 headers: { "Authorization" => headers["authorization"],
                                            "Idempotency-Key" => headers["idempotency-key"] },
                                 body:)
        json = JSON.generate(answer.body)
        client.write("HTTP/1.1 #{answer.status} OK\r\nContent-Type: application/json\r\n" \
                     "Content-Length: #{json.bytesize}\r\nConnection: close\r\n\r\n#{json}")
        client.close
      rescue IOError, Errno::EBADF
        break
      end
    end

    log = Tempfile.new("relay-worker")
    runner = <<~RUBY
      WebMock.disable_net_connect!(allow_localhost: true)
      SolidQueue::Supervisor.start
    RUBY
    child_env = ENV.to_h.slice(*%w[PATH HOME GEM_HOME GEM_PATH BUNDLE_PATH BUNDLE_APP_CONFIG]).merge(
      "RAILS_ENV" => "test",
      Timekeeping::Environment::DATABASE_URL => Timekeeping::Environment.database_url,
      Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => snapshot_url,
      Timekeeping::Environment::SERVICE_TOKEN => token
    )
    finished_relay_runs_since = lambda do |time|
      ApplicationRecord.connection.select_value(ApplicationRecord.sanitize_sql_array(
        ["SELECT COUNT(*) FROM solid_queue_jobs WHERE class_name = 'RelayJob' AND created_at > ? AND finished_at IS NOT NULL", time]
      )).to_i
    end
    wait_for = lambda do |what, seconds, &condition|
      deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + seconds
      until condition.call
        if Process.clock_gettime(Process::CLOCK_MONOTONIC) > deadline
          raise "#{what} not seen within #{seconds}s. Worker output:\n#{File.read(log.path)}"
        end
        sleep 0.25
      end
    end

    pid = nil
    begin
      pid = Process.spawn(child_env, RbConfig.ruby, "bin/rails", "runner", runner,
                          chdir: app_root, unsetenv_others: true, pgroup: true, out: log.path, err: log.path)

      with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => token) do
        post "/internal/v1/test-hooks/relay/pause", headers: { "Authorization" => "Bearer #{token}" }
        expect(response).to have_http_status(:success)

        stamp = Time.utc(2026, 3, 2, 9)
        OutboxSnapshot.insert_all!([{
          outbox_position: 1, id: 9601, project_id: 3, user_id: 4, work_date: "2026-03-02", duration: 60.0,
          bill_status: "unbilled", review_status: "not_required", locked: false, source: "manual",
          source_metadata: {}, proof_metadata: {}, created_at: stamp, updated_at: stamp,
          company_id: 1, version: 1, generation: TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION
        }])
        inserted_at = Time.current

        # "A configuration that names `RelayJob` but never schedules it would pass these assertions."
        # A scheduled run must finish while paused, or this wait fails.
        wait_for.call("a RelayJob run finished by the worker while paused", 45) { finished_relay_runs_since.call(inserted_at) >= 1 }
        # "Include pause and resume across the request and worker processes so the same check covers the required process boundary."
        expect(posted_lock.synchronize { posted_entry_ids.dup }).to be_empty
        expect(OutboxSnapshot.find_by!(outbox_position: 1).sent_at).to be_nil
        expect(projection.projected_entry(9601)).to be_nil

        post "/internal/v1/test-hooks/relay/resume", headers: { "Authorization" => "Bearer #{token}" }
        expect(response).to have_http_status(:success)
      end

      # "inserts a committed outbox row, and observes delivery to the fake projection endpoint without calling the job directly."
      wait_for.call("delivery of entry 9601 after resume", 25) { OutboxSnapshot.find_by!(outbox_position: 1).sent_at.present? }
      delivered_at = Time.current
      wait_for.call("a further RelayJob run after delivery", 25) { finished_relay_runs_since.call(delivered_at) >= 1 }

      expect(projection.projected_entry(9601)).to include("id" => 9601, "version" => 1, "company_id" => 1)
      expect(posted_lock.synchronize { posted_entry_ids.count(9601) }).to eq(1)
    ensure
      Timekeeping::TestHooks.resume_relay!
      if pid
        begin
          Process.kill("TERM", -pid)
          deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + 10
          sleep 0.2 while Process.waitpid(pid, Process::WNOHANG).nil? && Process.clock_gettime(Process::CLOCK_MONOTONIC) < deadline
          Process.kill("KILL", -pid)
          Process.waitpid(pid)
        rescue Errno::ESRCH, Errno::ECHILD
          nil
        end
      end
      listener.close
      listener_thread.join(2)
      log.close!
      ApplicationRecord.connection.execute(<<~SQL.squish)
        TRUNCATE outbox_snapshots, solid_queue_blocked_executions, solid_queue_claimed_executions,
          solid_queue_failed_executions, solid_queue_pauses, solid_queue_processes, solid_queue_ready_executions,
          solid_queue_recurring_executions, solid_queue_recurring_tasks, solid_queue_scheduled_executions,
          solid_queue_semaphores, solid_queue_jobs CASCADE
      SQL
    end

    expect(File.exist?(Timekeeping::TestHooks.relay_pause_file)).to be(false)
    expect { Process.kill(0, -pid) }.to raise_error(Errno::ESRCH)
  end
end
